// Generated by OrchestKit Claude Plugin
// Created: 2026-08-12 (#3321)

/**
 * PreCompact stdout contract — executed against the real dispatcher.
 *
 * On PreCompact, a command hook's STDOUT is not an envelope channel. CC's
 * PreCompact aggregator (verified in the shipped 2.1.228 binary) collects it
 * as the compaction summarizer's custom instructions:
 *
 *   a = results.filter(d => d.succeeded && !d.blocked && d.output.trim())
 *   return { newCustomInstructions: a.join('\n\n'), ... }
 *
 * and for a command hook `output` is literally the process stdout when it
 * exits 0 (`D = M ? (json.reason || stderr || "") : status===0 ? stdout : stderr`).
 * `newCustomInstructions` is then passed as `customInstructions` into the
 * summary request. So every ork PreCompact hook printing the usual
 * {"continue":true,"suppressOutput":true} was injecting that JSON into the
 * prompt that writes the session summary, on every compaction.
 *
 * This test spawns the real bin/run-hook.mjs rather than importing a handler,
 * because the defect lives in the emit path, not in any hook's return value —
 * a unit test on the handler would have passed throughout.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import { join, dirname } from 'node:path';

const HOOKS_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const RUN_HOOK = join(HOOKS_ROOT, 'bin', 'run-hook.mjs');

/**
 * An EMPTY project dir, not the repo. pre-compact-guard reads the real
 * `.claude/logs/subagent-spawns.jsonl` under CLAUDE_PROJECT_DIR, so pointing
 * at a live checkout makes this test pass or fail depending on whether the
 * developer running it happens to have background agents in flight.
 */
let projectDir: string;

beforeAll(() => {
  projectDir = mkdtempSync(join(tmpdir(), 'ork-precompact-contract-'));
});

afterAll(() => {
  rmSync(projectDir, { recursive: true, force: true });
});

function runHook(hookName: string, payload: Record<string, unknown>): string {
  return execFileSync(process.execPath, [RUN_HOOK, hookName], {
    input: JSON.stringify(payload),
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_PROJECT_DIR: projectDir },
    stdio: ['pipe', 'pipe', 'pipe'],
  });
}

const PRE_COMPACT = {
  hook_event_name: 'PreCompact',
  trigger: 'manual' as const,
  session_id: 'precompact-contract-probe',
  transcript_path: '/nonexistent-transcript.jsonl',
};

const PRECOMPACT_HOOKS = [
  'lifecycle/pre-compact-guard',
  'lifecycle/pre-compact-saver',
  'lifecycle/pre-compact-task-done-prompt',
  'lifecycle/webhook-forwarder',
];

describe('PreCompact stdout contract (#3321)', () => {
  it.each(PRECOMPACT_HOOKS)(
    '%s writes nothing to stdout when it does not block',
    (hookName) => {
      expect(runHook(hookName, PRE_COMPACT).trim()).toBe('');
    },
  );

  it('never emits a JSON envelope on PreCompact', () => {
    for (const hookName of PRECOMPACT_HOOKS) {
      // The specific string that was reaching the summarizer.
      expect(runHook(hookName, PRE_COMPACT)).not.toContain('"continue"');
    }
  });

  it('DOES emit the envelope when a PreCompact hook blocks', () => {
    // The other half of the contract. CC reads a block from `json.reason`, and
    // excludes blocked hooks from the instruction join — so a block must still
    // print, or the veto lands with no message (the #3321 claim 6 failure).
    const blockDir = mkdtempSync(join(tmpdir(), 'ork-precompact-block-'));
    try {
      const logPath = join(blockDir, '.claude', 'logs', 'subagent-spawns.jsonl');
      mkdirSync(dirname(logPath), { recursive: true });
      writeFileSync(
        logPath,
        `${JSON.stringify({
          timestamp: new Date().toISOString(),
          agent_id: 'agt_probe',
          subagent_type: 'general-purpose',
          source: 'start',
        })}\n`,
        'utf8',
      );

      const out = execFileSync(process.execPath, [RUN_HOOK, 'lifecycle/pre-compact-guard'], {
        input: JSON.stringify(PRE_COMPACT),
        encoding: 'utf8',
        env: { ...process.env, CLAUDE_PROJECT_DIR: blockDir },
        stdio: ['pipe', 'pipe', 'pipe'],
      });

      const parsed = JSON.parse(out) as Record<string, unknown>;
      expect(parsed.decision).toBe('block');
      expect(String(parsed.reason)).toContain('background agent');
    } finally {
      rmSync(blockDir, { recursive: true, force: true });
    }
  });

  it('keeps the envelope on other events — the fix is PreCompact-scoped', () => {
    // Same hook, different event: webhook-forwarder is registered on both
    // PreCompact and PostCompact, so a name-based fix would have broken this.
    const out = runHook('lifecycle/webhook-forwarder', {
      hook_event_name: 'PostCompact',
      session_id: 'precompact-contract-probe',
    });
    expect(out).toContain('"continue"');
  });

  it('keeps the envelope for a PostToolUse hook', () => {
    const out = runHook('posttool/context-crossing-warn', {
      hook_event_name: 'PostToolUse',
      session_id: 'precompact-contract-probe',
      tool_name: 'Read',
      tool_input: {},
      tool_output: 'hello',
    });
    expect(out).toContain('"continue"');
  });
});
